create or replace function public.adjust_schoolpro_inventory(p_asset uuid,p_delta integer,p_condition text default null,p_location text default null) returns integer language plpgsql security definer set search_path='public' as $$ declare a schoolpro_inventory_assets%rowtype; q int; begin select * into a from schoolpro_inventory_assets where id=p_asset for update; if a.id is null then raise exception 'Asset not found'; end if; if not schoolpro_member_can_manage(a.school_id) then raise exception 'Not authorized'; end if; q:=a.quantity+p_delta; if q<0 then raise exception 'Inventory cannot become negative'; end if; update schoolpro_inventory_assets set quantity=q,condition=coalesce(p_condition,condition),location=coalesce(p_location,location) where id=p_asset; return q; end $$;
create or replace function public.allocate_schoolpro_hostel(p_room uuid,p_student uuid,p_session text) returns uuid language plpgsql security definer set search_path='public' as $$ declare r schoolpro_hostel_rooms%rowtype; aid uuid; begin select * into r from schoolpro_hostel_rooms where id=p_room for update; if r.id is null then raise exception 'Room not found'; end if; if not schoolpro_member_can_manage(r.school_id) then raise exception 'Not authorized'; end if; if r.occupied>=r.capacity then raise exception 'Room is full'; end if; if not exists(select 1 from schoolpro_students where id=p_student and school_id=r.school_id) then raise exception 'Student is outside this school'; end if; update schoolpro_hostel_allocations set active=false where school_id=r.school_id and student_id=p_student and active=true; insert into schoolpro_hostel_allocations(school_id,student_id,room_id,session,active) values(r.school_id,p_student,p_room,p_session,true) returning id into aid; update schoolpro_hostel_rooms set occupied=(select count(*) from schoolpro_hostel_allocations where room_id=p_room and active=true) where id=p_room; return aid; end $$;
create or replace function public.assign_schoolpro_transport(p_route uuid,p_student uuid,p_pickup text) returns uuid language plpgsql security definer set search_path='public' as $$ declare r schoolpro_transport_routes%rowtype; aid uuid; begin select * into r from schoolpro_transport_routes where id=p_route; if r.id is null then raise exception 'Route not found'; end if; if not schoolpro_member_can_manage(r.school_id) then raise exception 'Not authorized'; end if; if not exists(select 1 from schoolpro_students where id=p_student and school_id=r.school_id) then raise exception 'Student is outside this school'; end if; update schoolpro_student_transport set active=false where school_id=r.school_id and student_id=p_student and active=true; insert into schoolpro_student_transport(school_id,student_id,route_id,pickup_point,active) values(r.school_id,p_student,p_route,p_pickup,true) returning id into aid; return aid; end $$;
create or replace function public.process_schoolpro_payroll(p_record uuid) returns void language plpgsql security definer set search_path='public' as $$ declare r schoolpro_payroll_records%rowtype; begin select * into r from schoolpro_payroll_records where id=p_record; if r.id is null then raise exception 'Payroll record not found'; end if; if not schoolpro_member_can_manage(r.school_id) and not exists(select 1 from schoolpro_members m where m.school_id=r.school_id and m.user_id=auth.uid() and m.role::text in ('bursar','accountant')) then raise exception 'Not authorized'; end if; update schoolpro_payroll_records set net=greatest(coalesce(gross,0)-coalesce(deductions,0),0),status='processed' where id=p_record; end $$;

create table if not exists public.schoolpro_document_templates(
 id uuid primary key default gen_random_uuid(), school_id uuid not null references public.schoolpro_schools(id) on delete cascade,
 name text not null, document_type text not null, description text, source_format text not null check(source_format in('pdf','docx','image')),
 storage_path text not null, original_filename text not null, mime_type text not null, page_count integer,
 field_mappings jsonb not null default '[]'::jsonb, settings jsonb not null default '{}'::jsonb,
 is_active boolean not null default true, is_default boolean not null default false, version integer not null default 1,
 created_by uuid references auth.users(id), created_at timestamptz not null default now(), updated_at timestamptz not null default now(),
 unique(school_id,document_type,name,version));
create table if not exists public.schoolpro_document_issues(
 id uuid primary key default gen_random_uuid(), school_id uuid not null references public.schoolpro_schools(id) on delete cascade,
 template_id uuid references public.schoolpro_document_templates(id) on delete set null,
 student_id uuid references public.schoolpro_students(id) on delete set null, document_type text not null, title text not null,
 serial_number text not null default ('DOC-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,12))),
 payload jsonb not null default '{}'::jsonb, output_storage_path text, status text not null default 'draft' check(status in('draft','issued','revoked')),
 issued_at timestamptz, issued_by uuid references auth.users(id), created_at timestamptz not null default now(), unique(school_id,serial_number));
alter table public.schoolpro_document_templates enable row level security; alter table public.schoolpro_document_issues enable row level security;
grant select,insert,update,delete on public.schoolpro_document_templates to authenticated;
grant select,insert,update,delete on public.schoolpro_document_issues to authenticated;
create policy "school members read document templates" on public.schoolpro_document_templates for select to authenticated using (exists(select 1 from public.schoolpro_schools s where s.id=school_id and s.owner_id=auth.uid()) or exists(select 1 from public.schoolpro_members m where m.school_id=school_id and m.user_id=auth.uid()));
create policy "school managers manage document templates" on public.schoolpro_document_templates for all to authenticated using (public.schoolpro_member_can_manage(school_id)) with check (public.schoolpro_member_can_manage(school_id));
create policy "school members read document issues" on public.schoolpro_document_issues for select to authenticated using (exists(select 1 from public.schoolpro_schools s where s.id=school_id and s.owner_id=auth.uid()) or exists(select 1 from public.schoolpro_members m where m.school_id=school_id and m.user_id=auth.uid()) or exists(select 1 from public.schoolpro_students st where st.id=student_id and st.user_id=auth.uid()));
create policy "school managers manage document issues" on public.schoolpro_document_issues for all to authenticated using (public.schoolpro_member_can_manage(school_id) or exists(select 1 from public.schoolpro_members m where m.school_id=school_id and m.user_id=auth.uid() and m.role::text in('registrar','head_teacher','vice_principal'))) with check (public.schoolpro_member_can_manage(school_id) or exists(select 1 from public.schoolpro_members m where m.school_id=school_id and m.user_id=auth.uid() and m.role::text in('registrar','head_teacher','vice_principal')));
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('schoolpro-document-templates','schoolpro-document-templates',false,15728640,array['application/pdf','application/vnd.openxmlformats-officedocument.wordprocessingml.document','image/png','image/jpeg']) on conflict(id) do update set public=false,file_size_limit=excluded.file_size_limit,allowed_mime_types=excluded.allowed_mime_types;
create policy "schoolpro template objects read" on storage.objects for select to authenticated using(bucket_id='schoolpro-document-templates' and ((storage.foldername(name))[1] in (select s.id::text from public.schoolpro_schools s where s.owner_id=auth.uid()) or (storage.foldername(name))[1] in (select m.school_id::text from public.schoolpro_members m where m.user_id=auth.uid())));
create policy "schoolpro template objects insert" on storage.objects for insert to authenticated with check(bucket_id='schoolpro-document-templates' and (storage.foldername(name))[1] in (select s.id::text from public.schoolpro_schools s where s.owner_id=auth.uid() union select m.school_id::text from public.schoolpro_members m where m.user_id=auth.uid() and m.role::text in('proprietor','administrator','it_admin')));
create policy "schoolpro template objects update" on storage.objects for update to authenticated using(bucket_id='schoolpro-document-templates' and (storage.foldername(name))[1] in (select s.id::text from public.schoolpro_schools s where s.owner_id=auth.uid() union select m.school_id::text from public.schoolpro_members m where m.user_id=auth.uid() and m.role::text in('proprietor','administrator','it_admin'))) with check(bucket_id='schoolpro-document-templates' and (storage.foldername(name))[1] in (select s.id::text from public.schoolpro_schools s where s.owner_id=auth.uid() union select m.school_id::text from public.schoolpro_members m where m.user_id=auth.uid() and m.role::text in('proprietor','administrator','it_admin')));
create policy "schoolpro template objects delete" on storage.objects for delete to authenticated using(bucket_id='schoolpro-document-templates' and (storage.foldername(name))[1] in (select s.id::text from public.schoolpro_schools s where s.owner_id=auth.uid() union select m.school_id::text from public.schoolpro_members m where m.user_id=auth.uid() and m.role::text in('proprietor','administrator','it_admin')));

create unique index if not exists schoolpro_document_templates_one_default_per_type on public.schoolpro_document_templates(school_id,document_type) where is_default=true and is_active=true;

create or replace function public.set_schoolpro_default_document_template(p_template uuid)
returns void language plpgsql security definer set search_path='' as $$
declare t public.schoolpro_document_templates;
begin
 select * into t from public.schoolpro_document_templates where id=p_template;
 if t.id is null then raise exception 'Template not found'; end if;
 if not public.schoolpro_member_can_manage(t.school_id) then raise exception 'Not authorized'; end if;
 update public.schoolpro_document_templates set is_default=false,updated_at=now() where school_id=t.school_id and document_type=t.document_type and id<>t.id;
 update public.schoolpro_document_templates set is_default=true,is_active=true,updated_at=now() where id=t.id;
end$$;
revoke all on function public.set_schoolpro_default_document_template(uuid) from public,anon;
grant execute on function public.set_schoolpro_default_document_template(uuid) to authenticated,service_role;

create or replace function public.verify_schoolpro_document(p_serial text)
returns table(serial_number text,title text,document_type text,status text,issued_at timestamptz,school_name text,student_name text)
language sql stable security definer set search_path='' as $$
 select i.serial_number,i.title,i.document_type,i.status,i.issued_at,s.name,
        case when i.status='issued' then trim(coalesce(st.first_name,'')||' '||coalesce(st.last_name,'')) else null end
 from public.schoolpro_document_issues i
 join public.schoolpro_schools s on s.id=i.school_id
 left join public.schoolpro_students st on st.id=i.student_id and st.school_id=i.school_id
 where upper(i.serial_number)=upper(trim(p_serial))
 limit 1
$$;
revoke all on function public.verify_schoolpro_document(text) from public;
grant execute on function public.verify_schoolpro_document(text) to anon,authenticated,service_role;

create or replace function public.schoolpro_auto_create_admission_document()
returns trigger language plpgsql security definer set search_path='' as $$
declare t public.schoolpro_document_templates; st public.schoolpro_students;
begin
 if new.enrollment_status='enrolled' and new.admitted_student_id is not null and (old.enrollment_status is distinct from new.enrollment_status or old.admitted_student_id is distinct from new.admitted_student_id) then
   select * into t from public.schoolpro_document_templates where school_id=new.school_id and document_type='admission_letter' and is_default=true and is_active=true order by version desc limit 1;
   if t.id is not null and not exists(select 1 from public.schoolpro_document_issues i where i.school_id=new.school_id and i.document_type='admission_letter' and i.payload->>'application_id'=new.id::text) then
     select * into st from public.schoolpro_students where id=new.admitted_student_id and school_id=new.school_id;
     insert into public.schoolpro_document_issues(school_id,template_id,student_id,document_type,title,payload,status,issued_by)
     values(new.school_id,t.id,new.admitted_student_id,'admission_letter',t.name,
       jsonb_build_object('application_id',new.id,'student_name',trim(coalesce(st.first_name,'')||' '||coalesce(st.last_name,'')),'first_name',st.first_name,'last_name',st.last_name,'admission_number',st.admission_number,'class_name',st.class_name,'guardian_name',new.guardian_name,'issue_date',current_date::text),
       'draft',auth.uid());
   end if;
 end if;
 return new;
end$$;
revoke all on function public.schoolpro_auto_create_admission_document() from public,anon,authenticated;
grant execute on function public.schoolpro_auto_create_admission_document() to service_role;
drop trigger if exists trg_schoolpro_auto_admission_document on public.schoolpro_admissions;
create trigger trg_schoolpro_auto_admission_document after update of enrollment_status,admitted_student_id on public.schoolpro_admissions for each row execute function public.schoolpro_auto_create_admission_document();

-- DataSub provider market pricing control and audit
create table if not exists public.datasub_pricing_audit (id uuid primary key default gen_random_uuid(),offering_id uuid references public.datasub_catalog_offerings(id) on delete set null,provider_id uuid references public.datasub_providers(id) on delete set null,action text not null,field_name text,old_value jsonb,new_value jsonb,reason text,changed_by uuid references auth.users(id) on delete set null,created_at timestamptz not null default now());
alter table public.datasub_pricing_audit enable row level security;
grant select on public.datasub_pricing_audit to authenticated,service_role;
revoke insert,update,delete on public.datasub_pricing_audit from anon,authenticated;
drop policy if exists "datasub admins read pricing audit" on public.datasub_pricing_audit;
create policy "datasub admins read pricing audit" on public.datasub_pricing_audit for select to authenticated using (private.has_product_access('datasub','view'));

create or replace function public.datasub_admin_update_market_price(p_offering uuid,p_smart numeric,p_reseller numeric,p_api numeric,p_top numeric,p_reason text default 'manual market update') returns void language plpgsql security definer set search_path='' as $$ declare o public.datasub_catalog_offerings; uid uuid:=auth.uid(); begin if uid is null or not private.has_product_access('datasub','edit') then raise exception 'Not authorized'; end if; select * into o from public.datasub_catalog_offerings where id=p_offering for update; if o.id is null then raise exception 'Offering not found'; end if; if least(p_smart,p_reseller,p_api,p_top)<o.base_provider_cost then raise exception 'Selling price cannot be below current base provider cost'; end if; update public.datasub_catalog_offerings set smart_earner_price=p_smart,reseller_price=p_reseller,api_price=p_api,top_seller_price=p_top,updated_at=now() where id=o.id; insert into public.datasub_pricing_audit(offering_id,action,field_name,old_value,new_value,reason,changed_by) values(o.id,'PRICE_UPDATE','selling_prices',jsonb_build_object('smart',o.smart_earner_price,'reseller',o.reseller_price,'api',o.api_price,'top',o.top_seller_price),jsonb_build_object('smart',p_smart,'reseller',p_reseller,'api',p_api,'top',p_top),nullif(trim(p_reason),''),uid); end$$;
revoke all on function public.datasub_admin_update_market_price(uuid,numeric,numeric,numeric,numeric,text) from public,anon; grant execute on function public.datasub_admin_update_market_price(uuid,numeric,numeric,numeric,numeric,text) to authenticated,service_role;

create or replace function public.datasub_admin_bulk_market_adjust(p_service text default null,p_network text default null,p_plan_type text default null,p_tier text default 'smart_earner',p_mode text default 'percent',p_value numeric default 0,p_reason text default 'market adjustment') returns integer language plpgsql security definer set search_path='' as $$ declare r record; n int:=0; oldp numeric; newp numeric; uid uuid:=auth.uid(); begin if uid is null or not private.has_product_access('datasub','edit') then raise exception 'Not authorized'; end if; if p_tier not in ('smart_earner','reseller','api','top_seller') then raise exception 'Invalid tier'; end if; if p_mode not in ('percent','fixed') then raise exception 'Invalid adjustment mode'; end if; for r in select * from public.datasub_catalog_offerings o where (p_service is null or o.service_type=p_service) and (p_network is null or o.network=p_network) and (p_plan_type is null or o.plan_type=p_plan_type) loop oldp:=case p_tier when 'smart_earner' then r.smart_earner_price when 'reseller' then r.reseller_price when 'api' then r.api_price else r.top_seller_price end; newp:=case when p_mode='percent' then round(oldp*(1+p_value/100.0),2) else oldp+p_value end; newp:=greatest(newp,r.base_provider_cost); update public.datasub_catalog_offerings set smart_earner_price=case when p_tier='smart_earner' then newp else smart_earner_price end,reseller_price=case when p_tier='reseller' then newp else reseller_price end,api_price=case when p_tier='api' then newp else api_price end,top_seller_price=case when p_tier='top_seller' then newp else top_seller_price end,updated_at=now() where id=r.id; insert into public.datasub_pricing_audit(offering_id,action,field_name,old_value,new_value,reason,changed_by) values(r.id,'BULK_MARKET_ADJUST',p_tier,to_jsonb(oldp),to_jsonb(newp),nullif(trim(p_reason),''),uid); n:=n+1; end loop; return n; end$$;
revoke all on function public.datasub_admin_bulk_market_adjust(text,text,text,text,text,numeric,text) from public,anon; grant execute on function public.datasub_admin_bulk_market_adjust(text,text,text,text,text,numeric,text) to authenticated,service_role;

create or replace function public.datasub_admin_update_upstream_route(p_upstream uuid,p_cost numeric,p_active boolean,p_reason text default 'provider market update') returns void language plpgsql security definer set search_path='' as $$ declare u public.datasub_upstream_catalog; uid uuid:=auth.uid(); begin if uid is null or not private.has_product_access('datasub','edit') then raise exception 'Not authorized'; end if; if p_cost<0 then raise exception 'Provider cost cannot be negative'; end if; select * into u from public.datasub_upstream_catalog where id=p_upstream for update; if u.id is null then raise exception 'Upstream route not found'; end if; update public.datasub_upstream_catalog set provider_cost=p_cost,active=p_active,last_synced_at=now() where id=u.id; insert into public.datasub_pricing_audit(provider_id,action,field_name,old_value,new_value,reason,changed_by) values(u.provider_id,'UPSTREAM_ROUTE_UPDATE','provider_cost_active',jsonb_build_object('cost',u.provider_cost,'active',u.active),jsonb_build_object('cost',p_cost,'active',p_active),nullif(trim(p_reason),''),uid); update public.datasub_catalog_offerings o set base_provider_cost=coalesce((select min(u2.provider_cost) from public.datasub_catalog_routes r join public.datasub_upstream_catalog u2 on u2.id=r.upstream_catalog_id where r.offering_id=o.id and r.route_enabled and u2.active),o.base_provider_cost),updated_at=now() where exists(select 1 from public.datasub_catalog_routes r where r.offering_id=o.id and r.upstream_catalog_id=u.id); end$$;
revoke all on function public.datasub_admin_update_upstream_route(uuid,numeric,boolean,text) from public,anon; grant execute on function public.datasub_admin_update_upstream_route(uuid,numeric,boolean,text) to authenticated,service_role;

create or replace function public.datasub_admin_set_provider_state(p_provider uuid,p_active boolean,p_priority integer,p_reason text default 'admin provider control') returns void language plpgsql security definer set search_path='' as $$ declare p public.datasub_providers; a public.datasub_provider_activation_checks; uid uuid:=auth.uid(); begin if uid is null or not private.has_product_access('datasub','edit') then raise exception 'Not authorized'; end if; select * into p from public.datasub_providers where id=p_provider for update; if p.id is null then raise exception 'Provider not found'; end if; if p_active then select * into a from public.datasub_provider_activation_checks where provider_id=p.id; if not coalesce(a.credentials_configured,false) or not coalesce(a.health_verified,false) or not coalesce(a.balance_verified,false) or not coalesce(a.catalogue_verified,false) or not coalesce(a.routing_verified,false) then raise exception 'Provider activation checks are incomplete'; end if; end if; update public.datasub_providers set is_active=p_active,priority=greatest(1,p_priority),state=case when p_active and state='DISABLED' then 'HEALTHY' when not p_active then 'DISABLED' else state end,updated_at=now() where id=p.id; insert into public.datasub_pricing_audit(provider_id,action,field_name,old_value,new_value,reason,changed_by) values(p.id,'PROVIDER_STATE','active_priority',jsonb_build_object('active',p.is_active,'priority',p.priority),jsonb_build_object('active',p_active,'priority',greatest(1,p_priority)),nullif(trim(p_reason),''),uid); end$$;
revoke all on function public.datasub_admin_set_provider_state(uuid,boolean,integer,text) from public,anon; grant execute on function public.datasub_admin_set_provider_state(uuid,boolean,integer,text) to authenticated,service_role;

-- Secure DataSub transaction PIN authorization
create table if not exists public.datasub_transaction_pins(user_id uuid primary key references public.profiles(id) on delete cascade,pin_hash text not null,failed_attempts integer not null default 0,locked_until timestamptz,updated_at timestamptz not null default now());
alter table public.datasub_transaction_pins enable row level security; revoke all on public.datasub_transaction_pins from anon,authenticated; grant all on public.datasub_transaction_pins to service_role;
create or replace function public.datasub_has_transaction_pin() returns boolean language sql stable security definer set search_path='' as $$select auth.uid() is not null and exists(select 1 from public.datasub_transaction_pins where user_id=auth.uid())$$;
revoke all on function public.datasub_has_transaction_pin() from public,anon; grant execute on function public.datasub_has_transaction_pin() to authenticated,service_role;
create or replace function public.set_datasub_transaction_pin(p_pin text,p_current_pin text default null) returns void language plpgsql security definer set search_path='' as $$declare uid uuid:=auth.uid(); old public.datasub_transaction_pins; begin if uid is null then raise exception 'Authentication required'; end if; if p_pin !~ '^[0-9]{4}$' then raise exception 'PIN must be exactly 4 digits'; end if; select * into old from public.datasub_transaction_pins where user_id=uid for update; if old.user_id is not null and (p_current_pin is null or crypt(p_current_pin,old.pin_hash)<>old.pin_hash) then raise exception 'Current PIN is incorrect'; end if; insert into public.datasub_transaction_pins(user_id,pin_hash,failed_attempts,locked_until,updated_at) values(uid,crypt(p_pin,gen_salt('bf')),0,null,now()) on conflict(user_id) do update set pin_hash=excluded.pin_hash,failed_attempts=0,locked_until=null,updated_at=now(); end$$;
revoke all on function public.set_datasub_transaction_pin(text,text) from public,anon; grant execute on function public.set_datasub_transaction_pin(text,text) to authenticated,service_role;
create or replace function public.verify_datasub_transaction_pin(p_user uuid,p_pin text) returns boolean language plpgsql security definer set search_path='' as $$declare x public.datasub_transaction_pins; ok boolean; begin if current_user not in ('service_role','postgres','supabase_admin') then raise exception 'Service role only'; end if; select * into x from public.datasub_transaction_pins where user_id=p_user for update; if x.user_id is null then return false; end if; if x.locked_until is not null and x.locked_until>now() then return false; end if; ok:=crypt(coalesce(p_pin,''),x.pin_hash)=x.pin_hash; if ok then update public.datasub_transaction_pins set failed_attempts=0,locked_until=null,updated_at=now() where user_id=p_user; else update public.datasub_transaction_pins set failed_attempts=case when failed_attempts>=4 then 0 else failed_attempts+1 end,locked_until=case when failed_attempts>=4 then now()+interval '15 minutes' else locked_until end,updated_at=now() where user_id=p_user; end if; return ok; end$$;
revoke all on function public.verify_datasub_transaction_pin(uuid,text) from public,anon,authenticated; grant execute on function public.verify_datasub_transaction_pin(uuid,text) to service_role;

