create or replace function public.finalize_schoolpro_billstack_transfer(p_intent uuid,p_transaction_ref text,p_verified_amount numeric,p_payload jsonb default '{}'::jsonb) returns jsonb language plpgsql security definer set search_path='' as $$
declare i public.schoolpro_payment_intents%rowtype; inv public.schoolpro_invoices%rowtype; existing uuid; receipt uuid; new_paid numeric;
begin
 select * into i from public.schoolpro_payment_intents where id=p_intent for update;
 if i.id is null then raise exception 'Payment intent not found'; end if;
 if i.gateway<>'billstack' then raise exception 'Payment intent provider mismatch'; end if;
 if i.status='successful' then return jsonb_build_object('status','already_credited','reference',i.reference); end if;
 if i.status<>'pending' then raise exception 'Payment intent is not payable'; end if;
 if p_verified_amount<>i.amount then raise exception 'Verified amount does not match invoice payment intent'; end if;
 select id into existing from public.schoolpro_fee_payments where reference=p_transaction_ref limit 1;
 if existing is not null then raise exception 'Transaction already applied'; end if;
 select * into inv from public.schoolpro_invoices where id=i.invoice_id for update;
 if inv.id is null or inv.school_id<>i.school_id or inv.student_id<>i.student_id then raise exception 'Invoice mapping mismatch'; end if;
 if inv.status in ('paid','waived') or inv.amount_paid+i.amount>inv.amount_due then raise exception 'Invoice is no longer payable'; end if;
 insert into public.schoolpro_fee_payments(school_id,invoice_id,student_id,amount,method,reference,notes,recorded_by) values(i.school_id,i.invoice_id,i.student_id,i.amount,'transfer',p_transaction_ref,'Verified BillStack bank transfer',i.payer_user_id) returning id into receipt;
 new_paid:=inv.amount_paid+i.amount;
 update public.schoolpro_invoices set amount_paid=new_paid,status=case when new_paid>=amount_due then 'paid'::public.schoolpro_invoice_status else 'part_paid'::public.schoolpro_invoice_status end,updated_at=now() where id=inv.id;
 update public.schoolpro_payment_intents set status='successful',gateway_transaction_id=p_transaction_ref,gateway_payload=coalesce(p_payload,'{}'::jsonb),credited_at=now(),updated_at=now() where id=i.id;
 return jsonb_build_object('status','credited','reference',i.reference,'receipt_id',receipt,'amount',i.amount);
end $$;
