begin select * into i from public.host_payment_intents where id=p_intent for update;if i.id is null then raise exception 'Host payment intent not found';end if;if i.status='paid' then return jsonb_build_object('status','already_paid');end if;if i.status<>'pending' or i.amount<>p_amount then raise exception 'Host payment mismatch';end if;select * into o from public.host_orders where id=i.order_id for update;if o.id is null or o.user_id<>i.user_id or o.amount<>p_amount then raise exception 'Host order mismatch';end if;
