create or replace function public.create_host_order(p_order_type text,p_domain text default null,p_plan uuid default null,p_domain_price uuid default null,p_cycle integer default 12,p_notes text default null) returns jsonb language plpgsql security definer set search_path='' as $$
declare pl public.host_plans%rowtype;dp public.host_domain_prices%rowtype;amt numeric;oid uuid;iid uuid;ord text;inv text;
begin if auth.uid() is null then raise exception 'Authentication required';end if;if p_cycle not in(1,12,24) then raise exception 'Invalid billing cycle';end if;
if p_order_type='domain_registration' then select * into dp from public.host_domain_prices where id=p_domain_price and is_active;if dp.id is null or p_domain is null or lower(p_domain) not like '%'||lower(dp.extension) then raise exception 'Invalid domain product';end if;amt:=dp.registration_price;p_cycle:=12;
else select * into pl from public.host_plans where id=p_plan and is_active;if pl.id is null then raise exception 'Invalid hosting plan';end if;amt:=pl.monthly_price*p_cycle;end if;
if amt<=0 then raise exception 'Invalid order amount';end if;
insert into public.host_orders(user_id,order_type,domain_name,plan_id,billing_cycle_months,amount,status,payment_status,provisioning_status,customer_notes) values(auth.uid(),p_order_type,nullif(lower(btrim(p_domain)),''),pl.id,p_cycle,amt,'awaiting_payment','unpaid','not_started',p_notes) returning id,order_number into oid,ord;
insert into public.host_invoices(user_id,order_id,amount,status,due_at) values(auth.uid(),oid,amt,'unpaid',current_date+7) returning id,invoice_number into iid,inv;
return jsonb_build_object('order_id',oid,'order_number',ord,'invoice_id',iid,'invoice_number',inv,'amount',amt);
end $$;
