create or replace function public.create_host_renewal_order(p_service uuid) returns jsonb language plpgsql security definer set search_path='' as $$
declare s public.host_services%rowtype;o public.host_orders%rowtype;dp public.host_domain_prices%rowtype;pl public.host_plans%rowtype;amt numeric;oid uuid;iid uuid;ord text;inv text;
