insert into public.host_invoices(user_id,order_id,amount,status,due_at) values(auth.uid(),oid,amt,'unpaid',current_date+7) returning id,invoice_number into iid,inv;return jsonb_build_object('order_id',oid,'order_number',ord,'invoice_id',iid,'invoice_number',inv,'amount',amt);
