create or replace function public.complete_host_provisioning(p_order uuid,p_provider_reference text,p_control_panel_url text default null,p_nameservers jsonb default '[]'::jsonb) returns jsonb language plpgsql security definer set search_path='' as $$
declare o public.host_orders%rowtype;s public.host_services%rowtype;stype text;sname text;
begin if not exists(select 1 from public.profiles p where p.id=auth.uid() and p.role::text in('super_admin','admin','operations')) then raise exception 'Permission denied';end if;select * into o from public.host_orders where id=p_order for update;if o.id is null or o.payment_status<>'paid' then raise exception 'Paid order required before provisioning';end if;
if o.renewal_service_id is not null then update public.host_services set status='active',provider_reference=coalesce(p_provider_reference,provider_reference),renews_at=coalesce(renews_at,current_date)+(o.billing_cycle_months||' months')::interval,updated_at=now() where id=o.renewal_service_id returning * into s;
